//! Native job vectors (P04.4): full session transcripts pinning the
//! real stage script per mode. Fixture trees are real
//! `encodeAdmittedTreeJson` outputs; every algorithm value/message ran
//! through the real TS (`parseArtifactText`, `assertLockstep`,
//! `checkCompatibility`, `installedFromTree`,
//! `checkCompilerVersionMatch`). Trace shapes (stages, tokens,
//! refusal codes/positions) pin the stage contract, including the
//! preview-warning vs confirmed-refusal compiler distinction.
//! Regenerate with `bun /tmp/p044-vectors.ts` plus this emitter.
use std::io::Write;
use std::process::{Command, Stdio};

fn binary() -> String {
    env!("CARGO_BIN_EXE_can-preparation").to_string()
}

fn frame(tag: u8, payload: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(5 + payload.len());
    out.push(tag);
    out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    out.extend_from_slice(payload);
    out
}

fn json_frame(value: &serde_json::Value) -> Vec<u8> {
    frame(0, &serde_json::to_vec(value).unwrap())
}

struct Case {
    id: &'static str,
    begin: &'static str,
    resumes: &'static [&'static str],
    expected: &'static [&'static str],
    exit: i32,
}

fn run_case(case: &Case) {
    let mut input = json_frame(&serde_json::json!({"protocol": "can-preparation", "version": 1}));
    let begin: serde_json::Value = serde_json::from_str(case.begin).unwrap();
    input.extend_from_slice(&json_frame(&begin));
    for (index, resume_json) in case.resumes.iter().enumerate() {
        let payload: serde_json::Value = serde_json::from_str(resume_json).unwrap();
        input.extend_from_slice(&json_frame(&serde_json::json!({
            "resume": {"token": (index as u64) + 1, "payload": payload}
        })));
    }
    let mut child = Command::new(binary())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(&input).unwrap();
    let output = child.wait_with_output().expect("binary ran");
    assert_eq!(
        output.status.code().unwrap(),
        case.exit,
        "{}: exit",
        case.id
    );
    // Stdout is protocol-only: accept + exactly the expected frames.
    let mut bytes = output.stdout.as_slice();
    let mut frames: Vec<serde_json::Value> = Vec::new();
    while bytes.len() >= 5 {
        let tag = bytes[0];
        let len = u32::from_le_bytes([bytes[1], bytes[2], bytes[3], bytes[4]]) as usize;
        assert_eq!(tag, 0, "{}: stdout tag", case.id);
        assert!(bytes.len() >= 5 + len, "{}: truncated stdout", case.id);
        frames.push(serde_json::from_slice(&bytes[5..5 + len]).unwrap());
        bytes = &bytes[5 + len..];
    }
    assert!(bytes.is_empty(), "{}: trailing stdout bytes", case.id);
    assert!(!frames.is_empty(), "{}: no frames", case.id);
    assert_eq!(frames[0]["ready"], true, "{}: accept", case.id);
    assert_eq!(
        frames[0]["protocol"], "can-preparation",
        "{}: accept",
        case.id
    );
    assert_eq!(frames[0]["version"], 1, "{}: accept", case.id);
    let rest = &frames[1..];
    assert_eq!(rest.len(), case.expected.len(), "{}: frame count", case.id);
    for (index, want_json) in case.expected.iter().enumerate() {
        let want: serde_json::Value = serde_json::from_str(want_json).unwrap();
        assert_eq!(rest[index], want, "{}: frame {index}", case.id);
    }
    // Stderr carries session diagnostics only, never protocol frames.
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        !stderr.contains("\"need\"") && !stderr.contains("\"prepared\""),
        "{}: protocol leak on stderr: {stderr}",
        case.id
    );
}

